from pathlib import Path
from urllib.parse import quote
import json

ROOT = Path(__file__).resolve().parents[2]
CH = 'src/pages/chapters/'
changed = []
staged = {}

def link(file, label, section=None):
    url = '#/chapter/' + quote(file.removesuffix('.md'))
    attrs = f' data-doc="{file}"'
    if section:
        url += '?section=' + quote(section)
        attrs += f' data-section="{section}"'
    return f'<a href="{url}"{attrs}>{label}</a>'

def ext(url, label):
    return f'<a href="{url}" target="_blank" rel="noreferrer">{label}</a>'

def edit(file, fn):
    p = ROOT / file
    raw = staged.get(file, p.read_bytes()).decode('utf-8')
    eol = '\r\n' if '\r\n' in raw else '\n'
    old = raw.replace('\r\n', '\n')
    new = fn(old)
    if new != old:
        staged[file] = new.replace('\n', eol).encode('utf-8')
        changed.append(file)

def replace(old, new, expected=1):
    def fn(text):
        n = text.count(old)
        if n != expected:
            raise ValueError(f'Expected {expected} occurrences, got {n}: {old[:100]}')
        return text.replace(old, new)
    return fn

def before(marker, snippet):
    return replace(marker, snippet.strip() + '\n\n    ' + marker)

def section(file, start, end, snippet):
    def fn(text):
        a = text.index(start)
        b = text.index(end, a + len(start))
        return text[:a] + snippet.strip() + '\n\n    ' + text[b:]
    edit(file, fn)

